import{_ as r,o as i,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Supporting 3 Availability Zones Stretch Cluster - Kamoltat (Junior) Sirivadhna, IBM","description":"","frontmatter":{"title":"Supporting 3 Availability Zones Stretch Cluster - Kamoltat (Junior) Sirivadhna, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Stretch Cluster","Availability Zones","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Supporting_3_Availability_Zones_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna_IBM.md","filePath":"posts/2025/Supporting_3_Availability_Zones_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Supporting_3_Availability_Zones_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna_IBM.md"};function n(s,t,a,u,p,_){return i(),l("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要-支持三可用区的ceph-stretch-cluster" tabindex="-1">会议纪要：支持三可用区的Ceph Stretch Cluster <a class="header-anchor" href="#会议纪要-支持三可用区的ceph-stretch-cluster" aria-label="Permalink to &quot;会议纪要：支持三可用区的Ceph Stretch Cluster&quot;">​</a></h3><p><strong>会议主题</strong>: 支持三可用区的Ceph Stretch Cluster<br><strong>主讲人</strong>: Junior, Ceph RADOS团队的工程师<br><strong>时间</strong>: 会议结束时的最后一场演讲<br><strong>参会人员</strong>: Ceph社区成员</p><h4 id="会议内容概述" tabindex="-1">会议内容概述： <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述：&quot;">​</a></h4><ol><li><p><strong>自我介绍与背景</strong>：</p><ul><li>Junior介绍了自己的背景，作为Ceph RADOS团队的工程师，他为Ceph贡献了四年多，主要负责Stretch Cluster、Stretch Mode、Autoscaler等功能。</li></ul></li><li><p><strong>Stretch Cluster简介</strong>：</p><ul><li>Stretch Cluster是一种跨多个地理位置的分布式存储集群，通常用于跨数据中心的场景，能够在数据中心故障时继续提供服务。</li></ul></li><li><p><strong>传统Stretch Cluster的挑战</strong>：</p><ul><li><strong>网络分裂</strong>：当两个数据中心之间的网络连接中断时，可能导致集群无法正常工作。</li><li><strong>Peering规则</strong>：在某些情况下可能导致数据丢失。</li></ul></li><li><p><strong>Stretch Mode的解决方案</strong>：</p><ul><li>引入第三个数据中心的Monitor（Tiebreaker Monitor）解决网络分裂问题。</li><li>在网络分裂时，将一个数据中心置于“黑暗模式”，集群在降级模式下运行。</li></ul></li><li><p><strong>Peering规则改进</strong>：</p><ul><li>新的Peering规则要求PG的acting set必须包含来自多个数据中心的OSD，以防止数据丢失。</li></ul></li><li><p><strong>扩展到三可用区的挑战</strong>：</p><ul><li>需要调整Peering规则，确保数据的分布和安全性。</li></ul></li><li><p><strong>当前的限制与解决方案</strong>：</p><ul><li><strong>网络分裂问题</strong>：需要实现机制来选择一个数据中心作为“黑暗模式”，并确保集群在两个可用区上继续运行。</li><li><strong>短期解决方案</strong>：Monitor中增加网络分裂检测功能。</li><li><strong>长期解决方案</strong>：选择一个数据中心作为“黑暗模式”。</li></ul></li><li><p><strong>三可用区的实现现状</strong>：</p><ul><li>三可用区的支持已经在Ceph的Squid版本和主分支中实现。</li></ul></li><li><p><strong>Q&amp;A环节</strong>：</p><ul><li>回答了关于负载、纠删码支持、三可用区与AAL集群兼容性的问题。</li></ul></li></ol><h4 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划： <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划：&quot;">​</a></h4><ul><li><strong>测试与验证</strong>：社区成员应测试三可用区的功能。</li><li><strong>长期解决方案开发</strong>：继续开发网络分裂检测和处理机制。</li><li><strong>纠删码支持</strong>：未来计划支持纠删码。</li></ul><p><strong>会议结束</strong>：感谢所有参会者的参与和支持，会议圆满结束。</p>',7)])])}const c=r(o,[["render",n]]);export{h as __pageData,c as default};
